  {
    "id": "20260830000000_reset_friendship_on_claim_asset",
    "sql": "CREATE OR REPLACE FUNCTION public.claim_asset_v2(\n  p_claim_id UUID\n) RETURNS JSONB AS $$\nDECLARE\n  v_caller_id UUID;\n  v_claim RECORD;\n  v_save JSONB;\n  v_new_save JSONB;\n  v_item_name TEXT;\n  v_qty INT;\n  v_curr_qty INT;\n  v_pokemon_data JSONB;\nBEGIN\n  v_caller_id := auth.uid();\n  SELECT * INTO v_claim FROM claim_queue WHERE id = p_claim_id FOR UPDATE;\n  IF NOT FOUND THEN RAISE EXCEPTION 'Reclamo no encontrado.'; END IF;\n  IF v_claim.user_id != v_caller_id THEN RAISE EXCEPTION 'No autorizado.'; END IF;\n  SELECT save_data INTO v_save FROM game_saves WHERE user_id = v_caller_id FOR UPDATE;\n  v_new_save := v_save;\n  CASE v_claim.asset_data->>'type'\n    WHEN 'pokemon' THEN\n      v_pokemon_data := jsonb_set(v_claim.asset_data->'data', '{friendship}', '70'::jsonb);\n      IF jsonb_array_length(v_new_save->'team') < 6 THEN\n        v_new_save := jsonb_set(v_new_save, '{team}', (v_new_save->'team') || jsonb_build_array(v_pokemon_data));\n      ELSE\n        v_new_save := jsonb_set(v_new_save, '{box}', COALESCE(v_new_save->'box', '[]'::jsonb) || jsonb_build_array(v_pokemon_data));\n      END IF;\n    WHEN 'money' THEN\n      v_new_save := jsonb_set(v_new_save, '{money}', to_jsonb((v_new_save->>'money')::BIGINT + (v_claim.asset_data->'data')::BIGINT));\n    WHEN 'item' THEN\n      v_item_name := v_claim.asset_data->'data'->>'name';\n      v_qty := COALESCE((v_claim.asset_data->'data'->>'qty')::INT, 1);\n      IF NOT (v_new_save ? 'inventory') OR v_new_save->'inventory' IS NULL THEN\n        v_new_save := jsonb_set(v_new_save, '{inventory}', '{}'::jsonb);\n      END IF;\n      v_curr_qty := COALESCE((v_new_save->'inventory'->>v_item_name)::INT, 0);\n      v_new_save := jsonb_set(\n        v_new_save, \n        ARRAY['inventory', v_item_name], \n        to_jsonb(v_curr_qty + v_qty)\n      );\n  END CASE;\n  UPDATE game_saves SET save_data = v_new_save, last_save_id = gen_random_uuid(), updated_at = NOW() WHERE user_id = v_caller_id;\n  DELETE FROM claim_queue WHERE id = p_claim_id;\n  RETURN v_new_save;\nEND;\n$$ LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_catalog;\nREVOKE EXECUTE ON FUNCTION public.claim_asset_v2(uuid) FROM PUBLIC, anon;\nGRANT EXECUTE ON FUNCTION public.claim_asset_v2(uuid) TO authenticated, service_role;\nINSERT INTO public.system_config (key, value) VALUES ('db_version', '20260830000000'::jsonb) ON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, updated_at = NOW();",
    "sqlite_sql": "INSERT INTO system_config (key, value) VALUES ('db_version', '\"20260830000000\"')\nON CONFLICT (key) DO UPDATE SET value = excluded.value, updated_at = CURRENT_TIMESTAMP;",
    "check": {
      "table": "claim_queue",
      "column": "id"
    }
  },
  {
    "id": "20260830190000_repair_all_player_saves",
    "sql": "DO $$\nDECLARE\n  r RECORD;\n  v_save_data JSONB;\n  v_team JSONB;\n  v_box JSONB;\n  v_eggs JSONB;\n  v_poke JSONB;\n  v_egg JSONB;\n  v_new_team JSONB;\n  v_new_box JSONB;\n  v_new_eggs JSONB;\n  v_inv JSONB;\n  v_new_inv JSONB;\n  v_key TEXT;\n  v_val JSONB;\nBEGIN\n  FOR r IN SELECT user_id, save_data FROM public.game_saves LOOP\n    v_save_data := r.save_data;\n    IF v_save_data IS NULL THEN\n      CONTINUE;\n    END IF;\n    IF jsonb_typeof(v_save_data) = 'string' THEN\n      BEGIN\n        v_save_data := (v_save_data #>> '{}')::jsonb;\n      EXCEPTION WHEN OTHERS THEN\n        CONTINUE;\n      END;\n    END IF;\n    IF jsonb_typeof(v_save_data) != 'object' THEN\n      CONTINUE;\n    END IF;\n    v_team := v_save_data -> 'team';\n    IF v_team IS NOT NULL AND jsonb_typeof(v_team) = 'array' THEN\n      v_new_team := '[]'::jsonb;\n      FOR v_poke IN SELECT * FROM jsonb_array_elements(v_team) LOOP\n        IF v_poke IS NOT NULL AND jsonb_typeof(v_poke) = 'object' THEN\n          IF (coalesce(v_poke ->> 'level', '1'))::int >= 100 THEN\n            v_poke := jsonb_set(v_poke, '{expNeeded}', '0'::jsonb);\n          ELSIF v_poke -> 'expNeeded' IS NULL OR jsonb_typeof(v_poke -> 'expNeeded') = 'null' OR jsonb_typeof(v_poke -> 'expNeeded') != 'number' THEN\n            v_poke := jsonb_set(v_poke, '{expNeeded}', '100'::jsonb);\n          END IF;\n          v_new_team := v_new_team || v_poke;\n        END IF;\n      END LOOP;\n      v_save_data := jsonb_set(v_save_data, '{team}', v_new_team);\n    END IF;\n    v_box := v_save_data -> 'box';\n    IF v_box IS NOT NULL AND jsonb_typeof(v_box) = 'array' THEN\n      v_new_box := '[]'::jsonb;\n      FOR v_poke IN SELECT * FROM jsonb_array_elements(v_box) LOOP\n        IF v_poke IS NOT NULL AND jsonb_typeof(v_poke) = 'object' THEN\n          IF (coalesce(v_poke ->> 'level', '1'))::int >= 100 THEN\n            v_poke := jsonb_set(v_poke, '{expNeeded}', '0'::jsonb);\n          ELSIF v_poke -> 'expNeeded' IS NULL OR jsonb_typeof(v_poke -> 'expNeeded') = 'null' OR jsonb_typeof(v_poke -> 'expNeeded') != 'number' THEN\n            v_poke := jsonb_set(v_poke, '{expNeeded}', '100'::jsonb);\n          END IF;\n          v_new_box := v_new_box || v_poke;\n        ELSIF v_poke IS NULL OR jsonb_typeof(v_poke) = 'null' THEN\n          v_new_box := v_new_box || 'null'::jsonb;\n        END IF;\n      END LOOP;\n      v_save_data := jsonb_set(v_save_data, '{box}', v_new_box);\n    END IF;\n    v_eggs := v_save_data -> 'eggs';\n    IF v_eggs IS NOT NULL AND jsonb_typeof(v_eggs) = 'array' THEN\n      v_new_eggs := '[]'::jsonb;\n      FOR v_egg IN SELECT * FROM jsonb_array_elements(v_eggs) LOOP\n        IF v_egg IS NOT NULL AND jsonb_typeof(v_egg) = 'object' THEN\n          IF v_egg -> 'id' IS NULL OR jsonb_typeof(v_egg -> 'id') = 'null' THEN\n            v_egg := jsonb_set(v_egg, '{id}', to_jsonb('egg_' || md5(random()::text)));\n          ELSIF jsonb_typeof(v_egg -> 'id') = 'number' THEN\n            v_egg := jsonb_set(v_egg, '{id}', to_jsonb('egg_' || md5(random()::text)));\n          END IF;\n          v_new_eggs := v_new_eggs || v_egg;\n        END IF;\n      END LOOP;\n      v_save_data := jsonb_set(v_save_data, '{eggs}', v_new_eggs);\n    END IF;\n    v_inv := v_save_data -> 'inventory';\n    IF v_inv IS NOT NULL AND jsonb_typeof(v_inv) = 'object' THEN\n      v_new_inv := '{}'::jsonb;\n      FOR v_key, v_val IN SELECT * FROM jsonb_each(v_inv) LOOP\n        IF jsonb_typeof(v_val) = 'number' AND (v_val::text)::numeric < 0 THEN\n          v_new_inv := jsonb_set(v_new_inv, ARRAY[v_key], '0'::jsonb);\n        ELSE\n          v_new_inv := jsonb_set(v_new_inv, ARRAY[v_key], v_val);\n        END IF;\n      END LOOP;\n      v_save_data := jsonb_set(v_save_data, '{inventory}', v_new_inv);\n    END IF;\n    IF v_save_data ? 'daycare' AND jsonb_typeof(v_save_data -> 'daycare') = 'object' THEN\n      IF (v_save_data -> 'daycare' -> 'parent1') IS NOT NULL AND jsonb_typeof(v_save_data -> 'daycare' -> 'parent1') = 'object' THEN\n        IF (coalesce(v_save_data -> 'daycare' -> 'parent1' ->> 'level', '1'))::int >= 100 THEN\n          v_save_data := jsonb_set(v_save_data, '{daycare,parent1,expNeeded}', '0'::jsonb);\n        ELSIF (v_save_data -> 'daycare' -> 'parent1' -> 'expNeeded') IS NULL OR jsonb_typeof(v_save_data -> 'daycare' -> 'parent1' -> 'expNeeded') = 'null' THEN\n          v_save_data := jsonb_set(v_save_data, '{daycare,parent1,expNeeded}', '100'::jsonb);\n        END IF;\n      END IF;\n      IF (v_save_data -> 'daycare' -> 'parent2') IS NOT NULL AND jsonb_typeof(v_save_data -> 'daycare' -> 'parent2') = 'object' THEN\n        IF (coalesce(v_save_data -> 'daycare' -> 'parent2' ->> 'level', '1'))::int >= 100 THEN\n          v_save_data := jsonb_set(v_save_data, '{daycare,parent2,expNeeded}', '0'::jsonb);\n        ELSIF (v_save_data -> 'daycare' -> 'parent2' -> 'expNeeded') IS NULL OR jsonb_typeof(v_save_data -> 'daycare' -> 'parent2' -> 'expNeeded') = 'null' THEN\n          v_save_data := jsonb_set(v_save_data, '{daycare,parent2,expNeeded}', '100'::jsonb);\n        END IF;\n      END IF;\n    END IF;\n    UPDATE public.game_saves SET save_data = v_save_data, last_save_id = gen_random_uuid() WHERE user_id = r.user_id;\n  END LOOP;\nEND $$;\nINSERT INTO public.system_config (key, value) VALUES ('db_version', '20260830190000'::jsonb) \nON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, updated_at = NOW();\nUPDATE public.game_saves SET last_save_id = gen_random_uuid();",
    "sqlite_sql": "UPDATE game_saves\nSET save_data = json_set(\n  save_data,\n  '$.team',\n  json(\n    (\n      SELECT json_group_array(\n        json_set(\n          team_item.value,\n          '$.expNeeded', CASE \n            WHEN CAST(coalesce(json_extract(team_item.value, '$.level'), 1) AS INTEGER) >= 100 THEN 0\n            WHEN json_extract(team_item.value, '$.expNeeded') IS NULL THEN 100\n            ELSE json_extract(team_item.value, '$.expNeeded')\n          END\n        )\n      )\n      FROM json_each(json_extract(game_saves.save_data, '$.team')) team_item\n      WHERE team_item.value IS NOT NULL AND json_type(team_item.value) = 'object'\n    )\n  )\n)\nWHERE save_data IS NOT NULL AND json_extract(save_data, '$.team') IS NOT NULL;\nUPDATE game_saves\nSET save_data = json_set(\n  save_data,\n  '$.box',\n  json(\n    (\n      SELECT json_group_array(\n        CASE \n          WHEN box_item.value IS NULL OR json_type(box_item.value) = 'null' THEN NULL\n          ELSE json_set(\n            box_item.value,\n            '$.expNeeded', CASE \n              WHEN CAST(coalesce(json_extract(box_item.value, '$.level'), 1) AS INTEGER) >= 100 THEN 0\n              WHEN json_extract(box_item.value, '$.expNeeded') IS NULL THEN 100\n              ELSE json_extract(box_item.value, '$.expNeeded')\n            END\n          )\n        END\n      )\n      FROM json_each(json_extract(game_saves.save_data, '$.box')) box_item\n    )\n  )\n)\nWHERE save_data IS NOT NULL AND json_extract(save_data, '$.box') IS NOT NULL;\nUPDATE game_saves\nSET save_data = json_set(\n  save_data,\n  '$.eggs',\n  json(\n    (\n      SELECT json_group_array(\n        json_set(\n          egg_item.value,\n          '$.id',\n          'egg_' || lower(hex(randomblob(4)))\n        )\n      )\n      FROM json_each(json_extract(game_saves.save_data, '$.eggs')) egg_item\n      WHERE egg_item.value IS NOT NULL AND json_type(egg_item.value) = 'object'\n    )\n  )\n)\nWHERE save_data IS NOT NULL AND json_extract(save_data, '$.eggs') IS NOT NULL;\nUPDATE game_saves\nSET save_data = json_set(\n  save_data,\n  '$.inventory',\n  json(\n    (\n      SELECT json_group_object(\n        inv.key,\n        CASE \n          WHEN CAST(inv.value AS INTEGER) < 0 THEN 0\n          ELSE CAST(inv.value AS INTEGER)\n        END\n      )\n      FROM json_each(json_extract(game_saves.save_data, '$.inventory')) inv\n      WHERE inv.value IS NOT NULL\n    )\n  )\n)\nWHERE save_data IS NOT NULL AND json_extract(save_data, '$.inventory') IS NOT NULL;\nINSERT INTO system_config (key, value) VALUES ('db_version', json('20260830190000'))\nON CONFLICT (key) DO UPDATE SET value = excluded.value, updated_at = CURRENT_TIMESTAMP;\nUPDATE game_saves SET last_save_id = lower(hex(randomblob(16)));",
    "check": null
  },
  {
    "id": "20260830200000_fix_egg_species_ids",
    "sql": "DO $$\nDECLARE\n  r RECORD;\n  v_save_data JSONB;\n  v_eggs JSONB;\n  v_egg JSONB;\n  v_new_eggs JSONB;\n  v_egg_species TEXT;\nBEGIN\n  FOR r IN SELECT user_id, save_data FROM public.game_saves LOOP\n    v_save_data := r.save_data;\n    IF v_save_data IS NULL THEN\n      CONTINUE;\n    END IF;\n    IF jsonb_typeof(v_save_data) = 'string' THEN\n      BEGIN\n        v_save_data := (v_save_data #>> '{}')::jsonb;\n      EXCEPTION WHEN OTHERS THEN\n        CONTINUE;\n      END;\n    END IF;\n    IF jsonb_typeof(v_save_data) != 'object' THEN\n      CONTINUE;\n    END IF;\n    v_eggs := v_save_data -> 'eggs';\n    IF v_eggs IS NOT NULL AND jsonb_typeof(v_eggs) = 'array' THEN\n      v_new_eggs := '[]'::jsonb;\n      FOR v_egg IN SELECT * FROM jsonb_array_elements(v_eggs) LOOP\n        IF v_egg IS NOT NULL AND jsonb_typeof(v_egg) = 'object' THEN\n          IF v_egg -> 'id' IS NULL OR jsonb_typeof(v_egg -> 'id') = 'null' OR jsonb_typeof(v_egg -> 'id') = 'number' OR (v_egg ->> 'id') LIKE 'egg_%' THEN\n            v_egg_species := COALESCE(\n              NULLIF(v_egg ->> 'pokemonId', ''),\n              NULLIF(v_egg ->> 'species', ''),\n              CASE\n                WHEN (v_egg ->> 'uid') LIKE '%-%' AND split_part(v_egg ->> 'uid', '-', 1) NOT LIKE 'egg%' THEN split_part(v_egg ->> 'uid', '-', 1)\n                ELSE NULL\n              END,\n              'togepi'\n            );\n            IF v_egg_species LIKE 'egg_%' OR v_egg_species = 'test_egg_uid' OR v_egg_species = 'egg' THEN\n              v_egg_species := 'togepi';\n            END IF;\n            v_egg := jsonb_set(v_egg, '{id}', to_jsonb(v_egg_species));\n          END IF;\n          v_new_eggs := v_new_eggs || v_egg;\n        END IF;\n      END LOOP;\n      v_save_data := jsonb_set(v_save_data, '{eggs}', v_new_eggs);\n      UPDATE public.game_saves SET save_data = v_save_data, last_save_id = gen_random_uuid() WHERE user_id = r.user_id;\n    END IF;\n  END LOOP;\nEND $$;\nINSERT INTO public.system_config (key, value) VALUES ('db_version', '20260830200000'::jsonb) \nON CONFLICT (key) DO UPDATE SET value = EXCLUDED.value, updated_at = NOW();\nUPDATE public.game_saves SET last_save_id = gen_random_uuid();",
    "sqlite_sql": "UPDATE game_saves\nSET save_data = json_set(\n  save_data,\n  '$.eggs',\n  json(\n    (\n      SELECT json_group_array(\n        json_set(\n          egg_item.value,\n          '$.id',\n          CASE\n            WHEN json_extract(egg_item.value, '$.pokemonId') IS NOT NULL AND json_extract(egg_item.value, '$.pokemonId') != '' AND json_extract(egg_item.value, '$.pokemonId') NOT LIKE 'egg_%' THEN json_extract(egg_item.value, '$.pokemonId')\n            WHEN json_extract(egg_item.value, '$.species') IS NOT NULL AND json_extract(egg_item.value, '$.species') != '' AND json_extract(egg_item.value, '$.species') NOT LIKE 'egg_%' THEN json_extract(egg_item.value, '$.species')\n            WHEN json_extract(egg_item.value, '$.id') IS NOT NULL AND json_type(egg_item.value, '$.id') = 'text' AND json_extract(egg_item.value, '$.id') NOT LIKE 'egg_%' AND json_extract(egg_item.value, '$.id') != '' THEN json_extract(egg_item.value, '$.id')\n            WHEN instr(coalesce(json_extract(egg_item.value, '$.uid'), ''), '-') > 1 AND substr(json_extract(egg_item.value, '$.uid'), 1, instr(json_extract(egg_item.value, '$.uid'), '-') - 1) NOT LIKE 'egg%' THEN substr(json_extract(egg_item.value, '$.uid'), 1, instr(json_extract(egg_item.value, '$.uid'), '-') - 1)\n            ELSE 'togepi'\n          END\n        )\n      )\n      FROM json_each(json_extract(game_saves.save_data, '$.eggs')) egg_item\n      WHERE egg_item.value IS NOT NULL AND json_type(egg_item.value) = 'object'\n    )\n  )\n)\nWHERE save_data IS NOT NULL AND json_extract(save_data, '$.eggs') IS NOT NULL;\nINSERT INTO system_config (key, value) VALUES ('db_version', json('20260830200000'))\nON CONFLICT (key) DO UPDATE SET value = excluded.value, updated_at = CURRENT_TIMESTAMP;\nUPDATE game_saves SET last_save_id = lower(hex(randomblob(16)));",
    "check": null
  }
